function geometryFromPositions(p){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(p,3));g.computeVertexNormals();return g;}
function exampleGeometry(kind){
  let g;
  if(kind==='bracket'){
    const sh=new THREE.Shape();sh.moveTo(0,0);sh.lineTo(90,0);sh.lineTo(90,8);sh.lineTo(17,8);sh.quadraticCurveTo(8,8,8,17);sh.lineTo(8,55);sh.lineTo(0,55);sh.closePath();
    for(const [x,y,r] of [[38,4,2.1],[75,4,2.1],[4,31,2.1]]){const hole=new THREE.Path();hole.absarc(x,y,r,0,Math.PI*2,true);sh.holes.push(hole);}
    g=new THREE.ExtrudeGeometry(sh,{depth:25,bevelEnabled:false,curveSegments:16,steps:1});
  }else if(kind==='bushing'){
    const sh=new THREE.Shape();sh.absarc(0,0,20,0,Math.PI*2,false);const h=new THREE.Path();h.absarc(0,0,10,0,Math.PI*2,true);sh.holes.push(h);g=new THREE.ExtrudeGeometry(sh,{depth:48,bevelEnabled:false,curveSegments:36,steps:1});
  }else{
    const sh=new THREE.Shape();sh.moveTo(-55,-35);sh.lineTo(55,-35);sh.lineTo(55,35);sh.lineTo(-55,35);sh.closePath();
    const h=new THREE.Path();h.moveTo(-52,-32);h.lineTo(-52,32);h.lineTo(52,32);h.lineTo(52,-32);h.closePath();sh.holes.push(h);
    g=new THREE.ExtrudeGeometry(sh,{depth:32,bevelEnabled:false,steps:1});
  }
  const a=g.index?g.toNonIndexed():g,p=new Float32Array(a.attributes.position.array);a.dispose();if(g!==a)g.dispose();return p;
}
